    "inlineSchema": "// =============================================================================\n// Trionda Wears — Complete Data Model\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // url is configured via prisma.config.ts and the Neon adapter at runtime\n}\n\n// =============================================================================\n// ENUMS\n// =============================================================================\n\nenum UserRole {\n  CUSTOMER\n  ADMIN\n}\n\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\nenum PaymentMethod {\n  JAZZCASH\n  EASYPAISA\n  COD\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\n// =============================================================================\n// PRODUCT CATALOG\n// =============================================================================\n\nmodel Category {\n  id          String     @id @default(cuid())\n  name        String\n  slug        String     @unique\n  description String?\n  parentId    String?\n  parent      Category?  @relation(\"CategoryTree\", fields: [parentId], references: [id], onDelete: Restrict)\n  children    Category[] @relation(\"CategoryTree\")\n  products    Product[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([parentId])\n}\n\nmodel Product {\n  id             String  @id @default(cuid())\n  name           String\n  slug           String  @unique\n  description    String?\n  basePrice      Decimal @db.Decimal(10, 2)\n  isCustomizable Boolean @default(false)\n  isActive       Boolean @default(true)\n\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n\n  variants ProductVariant[]\n  images   ProductImage[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([categoryId])\n  @@index([isActive])\n}\n\nmodel ProductVariant {\n  id            String   @id @default(cuid())\n  size          String?\n  color         String?\n  fabricType    String?\n  sku           String   @unique\n  price         Decimal? @db.Decimal(10, 2) // nullable: falls back to Product.basePrice\n  stockQuantity Int      @default(0)\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  orderItems OrderItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([productId])\n  @@index([sku])\n}\n\nmodel ProductImage {\n  id           String  @id @default(cuid())\n  url          String // Will be a Cloudinary URL in production\n  altText      String?\n  displayOrder Int     @default(0)\n\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([productId])\n}\n\n// =============================================================================\n// CUSTOM MEASUREMENTS (Made-to-Order)\n// =============================================================================\n\n// Standard measurements for tailored clothing (shirts, trousers, sherwanis, etc.)\nmodel CustomMeasurement {\n  id String @id @default(cuid())\n\n  // Upper body (shirts, sherwanis, kurtas)\n  chest        Decimal? @db.Decimal(5, 2) // in inches\n  waist        Decimal? @db.Decimal(5, 2)\n  shoulder     Decimal? @db.Decimal(5, 2)\n  sleeveLength Decimal? @db.Decimal(5, 2)\n  neck         Decimal? @db.Decimal(5, 2)\n\n  // Lower body (trousers, shalwars)\n  hip    Decimal? @db.Decimal(5, 2)\n  inseam Decimal? @db.Decimal(5, 2)\n  thigh  Decimal? @db.Decimal(5, 2)\n  rise   Decimal? @db.Decimal(5, 2)\n  cuff   Decimal? @db.Decimal(5, 2)\n\n  // General\n  height Decimal? @db.Decimal(5, 2)\n  notes  String?  @db.Text // Special instructions, fit preferences, etc.\n\n  // Relation to OrderItem (one-to-one: each order item with measurements has one set)\n  orderItem OrderItem?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// =============================================================================\n// USER & AUTH\n// =============================================================================\n\nmodel User {\n  id           String   @id @default(cuid())\n  email        String   @unique\n  passwordHash String\n  firstName    String\n  lastName     String\n  phone        String?\n  role         UserRole @default(CUSTOMER)\n\n  addresses Address[]\n  orders    Order[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n}\n\nmodel Address {\n  id           String  @id @default(cuid())\n  label        String // e.g. \"Home\", \"Work\", \"Parents' House\"\n  fullName     String\n  phone        String\n  addressLine1 String\n  addressLine2 String?\n  city         String\n  province     String // Province/State\n  postalCode   String?\n  country      String  @default(\"Pakistan\")\n  isDefault    Boolean @default(false)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Orders shipping to this address\n  shippingOrders Order[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n}\n\n// =============================================================================\n// ORDERS\n// =============================================================================\n\nmodel Order {\n  id            String        @id @default(cuid())\n  orderNumber   String        @unique // Human-readable: e.g. \"TRD-2026-000001\"\n  status        OrderStatus   @default(PENDING)\n  subtotal      Decimal       @db.Decimal(10, 2)\n  shippingCost  Decimal       @default(0) @db.Decimal(10, 2)\n  total         Decimal       @db.Decimal(10, 2)\n  paymentMethod PaymentMethod\n  paymentStatus PaymentStatus @default(PENDING)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Restrict)\n\n  shippingAddressId String\n  shippingAddress   Address @relation(fields: [shippingAddressId], references: [id], onDelete: Restrict)\n\n  items OrderItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([orderNumber])\n  @@index([status])\n}\n\nmodel OrderItem {\n  id              String  @id @default(cuid())\n  quantity        Int     @default(1)\n  priceAtPurchase Decimal @db.Decimal(10, 2) // Snapshot price at time of purchase\n\n  orderId String\n  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)\n\n  productVariantId String\n  productVariant   ProductVariant @relation(fields: [productVariantId], references: [id], onDelete: Restrict)\n\n  // Nullable: only set for made-to-order (customizable) items\n  customMeasurementId String?            @unique // One-to-one: each order item has at most one measurement set\n  customMeasurement   CustomMeasurement? @relation(fields: [customMeasurementId], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([orderId])\n  @@index([productVariantId])\n}\n",
